/**
 * Helper aman untuk mendapatkan atau membuat kategori (menggunakan wp_insert_term)
 */
function hakajobs_get_or_create_category($name, $parent_id = 0) {
    if (empty($name)) {
        return 0;
    }
    $term = term_exists($name, 'category');
    if ($term) {
        return is_array($term) ? (int)$term['term_id'] : (int)$term;
    }
    $args = array();
    if ($parent_id > 0) {
        $args['parent'] = (int)$parent_id;
    }
    $new_term = wp_insert_term($name, 'category', $args);
    if (!is_wp_error($new_term) && isset($new_term['term_id'])) {
        return (int)$new_term['term_id'];
    }
    return 0;
}

/**
 * Buat atau pastikan artikel panduan karir terbit di menu Pos
 */
function hakajobs_generate_starter_articles() {
    $raw_json = '[{"key": "skd", "title": "Latihan Soal SKD CPNS 2026: Materi TWK Integritas & Pengamalan Pancasila (10 Soal Lengkap + Pembahasan)", "category": "CPNS & BUMN", "tags": ["SKD CPNS", "TWK HOTS", "Pancasila", "Integritas KPK", "CAT BKN 2026"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Ringkasan Eksekutif:</strong> Artikel ini memuat panduan komprehensif menghadapi Seleksi Kompetensi Dasar (SKD) CPNS 2026 berdasarkan pedoman Badan Kepegawaian Negara (BKN) dan KemenPAN-RB. Dilengkapi analisis materi HOTS dan <strong>10 latihan soal lengkap dengan kunci serta pembahasan mendalam</strong> untuk menguji kesiapan Anda.\\n            </div>\\n\\n            <h2 id=\\"regulasi\\">1. Regulasi Resmi &amp; Nilai Ambang Batas (Passing Grade) SKD CPNS 2026</h2>\\n            <p>Seleksi Kompetensi Dasar (SKD) menggunakan sistem <em>Computer Assisted Test</em> (CAT) BKN dengan total <strong>110 butir soal</strong> yang wajib diselesaikan dalam tempo <strong>100 menit</strong> (130 menit untuk penyandang disabilitas sensori netra). Komposisi sub-tes meliputi:</p>\\n            <ul>\\n                <li><strong>Tes Wawasan Kebangsaan (TWK)</strong>: 30 butir soal. Bobot nilai jawaban benar = +5, salah/kosong = 0. Nilai Ambang Batas (Passing Grade) = <strong>65</strong> (skor maksimal 150).</li>\\n                <li><strong>Tes Inteligensi Umum (TIU)</strong>: 35 butir soal. Bobot nilai jawaban benar = +5, salah/kosong = 0. Nilai Ambang Batas = <strong>80</strong> (skor maksimal 175).</li>\\n                <li><strong>Tes Karakteristik Pribadi (TKP)</strong>: 45 butir soal. Sistem penilaian bertingkat skor 1 sampai 5 (tidak ada jawaban bernilai 0). Nilai Ambang Batas = <strong>166</strong> (skor maksimal 225).</li>\\n            </ul>\\n            <p><strong>Total Skor Maksimal SKD adalah 550 poin</strong>. Untuk lolos ke tahapan Seleksi Kompetensi Bidang (SKB), Anda wajib memenuhi ambang batas di ketiga sub-tes tersebut DAN masuk dalam kuota perankingan 3 kali formasi yang dibutuhkan.</p>\\n\\n            <h2 id=\\"karakteristik-hots\\">2. Karakteristik Soal TWK Tipe HOTS (Higher Order Thinking Skills)</h2>\\n            <p>Sejak beberapa tahun terakhir, BKN merombak total pola soal TWK. Soal berbasis hafalan tekstual (seperti tanggal konferensi atau nomor pasal undang-undang) telah digantikan oleh <strong>soal penalaran studi kasus nyata di tempat kerja</strong>. Karakteristik utamanya:</p>\\n            <ol>\\n                <li><strong>Studi Kasus Dilematis</strong>: Soal menyajikan narasi seorang ASN yang dihadapkan pada dua pilihan sulit (misalnya antara loyalitas atasan vs kepatuhan pada aturan hukum).</li>\\n                <li><strong>Pengamalan Sila Pancasila</strong>: Bukan sekadar menyebutkan butir sila, melainkan menentukan opsi tindakan mana yang paling mencerminkan keadilan sosial atau persatuan nasional.</li>\\n                <li><strong>9 Nilai Integritas Antikorupsi KPK</strong>: Meliputi <em>Jujur, Peduli, Mandiri, Disiplin, Tanggung Jawab, Kerja Keras, Sederhana, Berani, dan Adil</em> dalam birokrasi pemerintahan.</li>\\n                <li><strong>Bela Negara Kontemporer</strong>: Menyoroti pertahanan non-fisik, pencegahan radikalisme, ketahanan siber, dan kedaulatan ekonomi produk dalam negeri.</li>\\n            </ol>\\n\\n            <h2 id=\\"manajemen-waktu\\">3. Trik Manajemen Waktu 100 Menit untuk 110 Soal</h2>\\n            <p>Banyak peserta cerdas gagal bukan karena tidak mampu mengerjakan soal, melainkan karena kehabisan waktu di sub-tes hitungan matematika TIU. Terapkan urutan pengerjaan berikut:</p>\\n            <ul>\\n                <li><strong>Menit 01 - 30 (TKP - 45 Soal)</strong>: Kerjakan TKP di awal saat konsentrasi masih segar. Jangan pernah mengosongkan soal TKP karena semua opsi memiliki nilai 1 sampai 5. Alokasikan maksimal 40 detik per soal.</li>\\n                <li><strong>Menit 31 - 55 (TWK - 30 Soal)</strong>: Baca kalimat tanya terakhir pada paragraf cerita untuk menangkap inti persoalan. Eliminasi 2 opsi ekstrem terlebih dahulu. Alokasikan maksimal 50 detik per soal.</li>\\n                <li><strong>Menit 56 - 95 (TIU - 35 Soal)</strong>: Kerjakan terlebih dahulu analogi kata dan silogisme verbal. Untuk hitungan numerik, jika dalam 45 detik Anda belum menemukan polanya, lewati dulu dan tandai untuk dikerjakan terakhir.</li>\\n                <li><strong>Menit 96 - 100 (Review Jawaban)</strong>: Cek lembar navigasi soal CAT untuk memastikan tidak ada soal yang terlewat.</li>\\n            </ul>\\n\\n            <h2 id=\\"bank-soal-10\\">4. Bank Soal Latihan Mandiri (10 Soal Lengkap + Pembahasan Mendalam)</h2>\\n            <p>Uji pemahaman Anda sekarang juga dengan mengerjakan 10 latihan soal HOTS di bawah ini. Klik tombol <strong>\\"Buka Kunci Jawaban & Pembahasan\\"</strong> pada tiap butir soal setelah Anda memilih jawaban:</p>\\n\\n            \\n<div class=\\"hk-exam-score-card\\">\\n    <div class=\\"hk-exam-score-left\\">\\n        <span class=\\"hk-exam-score-label\\">📊 Lembar Evaluasi Interaktif SKD CPNS 2026:</span>\\n        <div class=\\"hk-exam-score-val\\" id=\\"hk-exam-score-display\\">0 / 10 Soal Terjawab</div>\\n        <div class=\\"hk-exam-score-sub\\" id=\\"hk-exam-score-status\\">Pilih jawaban Anda (opsi A, B, C, D, E) pada setiap butir soal di bawah lalu klik \\"Periksa Jawaban\\" untuk mengecek ambang batas kelulusan Anda secara instan.</div>\\n    </div>\\n    <div class=\\"hk-exam-score-right\\">\\n        <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle\\" >\\n            🔄 Ulangi Semua Soal\\n        </button>\\n    </div>\\n</div>\\n\\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-1\\" data-soal-num=\\"1\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #1</span>\\n                <span class=\\"hk-soal-category-tag\\">TWK HOTS • Pengamalan Sila ke-1 Pancasila</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-1\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Seorang aparatur sipil negara (ASN) yang bertugas di loket pelayanan kependudukan dihadapkan pada situasi di mana rekan satu timnya menolak melayani warga dengan alasan perbedaan keyakinan dan penampilan keagamaan warga tersebut. Tindakan yang paling mencerminkan integritas nilai Ketuhanan Yang Maha Esa dan profesionalisme ASN adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-1\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Membiarkan tindakan rekannya karena menghormati kebebasan berkeyakinan dan hak individu setiap rekan kerja.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Mengambil alih pelayanan warga tersebut secara ramah dan profesional, kemudian mendiskusikan serta mengingatkan rekan kerja secara bijak tentang kewajiban ASN bersikap netral tanpa diskriminasi.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Melaporkan rekan kerja tersebut secara anonim ke media sosial agar mendapat sanksi sosial dari masyarakat luas.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Menegur rekan kerja tersebut dengan keras di hadapan warga umum agar menimbulkan efek jera seketika.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Menyarankan warga tersebut untuk mencari petugas lain di meja sebelah yang memiliki keyakinan serupa.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-1\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-1\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-1\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Sila ke-1 \'Ketuhanan Yang Maha Esa\' dalam konteks pelayanan publik mewajibkan setiap abdi negara untuk menjamin kebebasan dan kesetaraan hak setiap warga negara tanpa diskriminasi SARA (Pasal 29 UUD 1945). Tindakan B mencerminkan tanggung jawab ganda: mengedepankan pelayanan prima bagi masyarakat tanpa penundaan, serta melakukan pembinaan internal secara etis dan konstruktif.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-2\\" data-soal-num=\\"2\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #2</span>\\n                <span class=\\"hk-soal-category-tag\\">TWK HOTS • 9 Nilai Integritas Antikorupsi KPK</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-2\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Sebagai staf bagian pengadaan barang dan jasa instansi, Anda menerima bingkisan mewah berupa gawai elektronik dari salah satu vendor pemenang lelang tender proyek sebagai ucapan terima kasih atas kerja sama selama 1 tahun. Vendor menyatakan bahwa bingkisan ini murni silaturahmi pribadi di luar kontrak resmi. Sikap integritas yang wajib diambil adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-2\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Menerima gawai tersebut karena proses lelang telah selesai secara sah dan vendor telah dinyatakan menang.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Menerima bingkisan tersebut lalu membagikannya kepada seluruh staf divisi agar tidak dinikmati secara pribadi.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Menolak bingkisan dengan sopan dan menjelaskan aturan gratifikasi, atau jika tidak dapat ditolak, segera melaporkannya ke Unit Pengendalian Gratifikasi (UPG) / KPK dalam waktu maksimal 30 hari kerja.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Menjual gawai tersebut dan mendonasikan uang hasil penjualannya ke yayasan panti asuhan.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Menyimpan barang tersebut di kantor tanpa membukanya sama sekali hingga masa jabatan berakhir.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-2\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-2\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-2\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Berdasarkan Pasal 12B UU No. 20 Tahun 2001 tentang Tindak Pidana Korupsi, setiap penerimaan fasilitas, uang, atau barang oleh penyelenggara negara yang berhubungan dengan jabatannya dikategorikan sebagai gratifikasi ilegal kecuali dilaporkan ke KPK dalam waktu paling lambat 30 hari kerja sejak tanggal penerimaan. Pilihan C adalah satu-satunya prosedur hukum yang benar.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-3\\" data-soal-num=\\"3\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #3</span>\\n                <span class=\\"hk-soal-category-tag\\">TWK HOTS • Bela Negara & Ketahanan Siber</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-3\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Dalam era transformasi digital, ancaman terhadap keutuhan bangsa tidak hanya berbentuk agresi militer fisik, melainkan perang siber (*cyber warfare*) dan infiltrasi informasi palsu (hoaks terkoordinasi). Perwujudan nilai dasar Bela Negara \'Kemampuan Awal Bela Negara\' oleh seorang tenaga profesional di bidang teknologi informasi adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-3\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Melakukan peretasan balasan (*counter hack*) ke situs pemerintah negara lain secara mandiri.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Menerapkan protokol keamanan siber yang ketat, mengamankan data rahasia instansi, serta aktif memverifikasi dan mengedukasi literasi digital anti-hoaks di lingkungan kerja.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Menghapus seluruh akun media sosial pribadi agar tidak menjadi sasaran empuk serangan phising.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Mengganti seluruh perangkat lunak kerja dengan aplikasi bajakan yang dimodifikasi tanpa izin lisensi.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Menyerahkan seluruh tanggung jawab keamanan sistem kepada pihak vendor luar negeri.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-3\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-3\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-3\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Kemampuan awal bela negara secara psikis dan fisik di era modern diwujudkan melalui penguasaan kompetensi profesional untuk menjaga kedaulatan informasi nasional. Mengamankan aset data instansi dan meningkatkan literasi digital publik adalah wujud nyata pertahanan nir-militer yang diamanatkan UU No. 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-4\\" data-soal-num=\\"4\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #4</span>\\n                <span class=\\"hk-soal-category-tag\\">TWK HOTS • Sila ke-3 Persatuan Indonesia</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-4\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Pemerintah menugaskan ASN muda dari Pulau Jawa untuk memimpin proyek pemberdayaan ekonomi masyarakat adat di wilayah pedalaman Papua. Pada pertemuan awal, beberapa tokoh adat menunjukkan sikap resistan karena trauma masa lalu dengan pejabat luar daerah. Pendekatan yang paling tepat sesuai semangat Bhinneka Tunggal Ika adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-4\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Memaksakan prosedur standar operasional pusat dengan ancaman pembatalan bantuan dana anggaran proyek.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Melakukan pendekatan kultural dengan mendengarkan aspirasi para tetua adat, menghormati hukum adat lokal yang tidak bertentangan dengan hukum nasional, dan melibatkan putra daerah dalam kepengurusan.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Meminta bantuan aparat keamanan bersenjata lengkap untuk mengawal setiap sesi rapat bersama warga.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Mengalihkan lokasi proyek ke desa lain yang masyarakatnya lebih mudah diatur dan bersikap ramah.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Hanya berinteraksi dengan warga pendatang yang memiliki kesamaan suku dan budaya asal.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-4\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-4\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-4\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Pengamalan Sila ke-3 dalam keberagaman menuntut empati kultural dan pendekatan persuasif partisipatif. Menghargai kearifan lokal (local wisdom) dan melibatkan masyarakat adat sebagai subjek pembangunan memperkuat kohesi nasional tanpa mencabut identitas budaya mereka.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-5\\" data-soal-num=\\"5\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #5</span>\\n                <span class=\\"hk-soal-category-tag\\">TWK HOTS • UUD 1945 Pasal 28 & Batasan Etika ASN</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-5\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Pasal 28E ayat (3) UUD 1945 menyatakan bahwa setiap orang berhak atas kebebasan berserikat, berkumpul, dan mengeluarkan pendapat. Namun bagi seorang Pegawai Negeri Sipil (PNS), kebebasan ini memiliki batasan etika profesi khusus, yaitu...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-5\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">PNS sama sekali tidak boleh memiliki opini pribadi dalam urusan politik kebangsaan.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">PNS bebas mengkritik kebijakan instansinya sendiri secara terbuka di media sosial dengan menggunakan akun anonim.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">PNS wajib menjaga netralitas, tidak boleh terlibat dalam politik praktis/kampanye pemilu, serta tidak menyebarkan rahasia negara atau ujaran kebencian yang meruntuhkan marwah korps ASN.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">PNS hanya boleh menyampaikan pendapat setelah mendapatkan surat izin tertulis dari menteri terkait.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">PNS tidak diperbolehkan menjadi anggota organisasi profesi resmi apapun.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-5\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-5\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-5\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> UU No. 20 Tahun 2023 tentang Aparatur Sipil Negara secara tegas mengatur asas netralitas ASN (Pasal 2 f dan Pasal 9 ayat 2). Hak asasi mengemukakan pendapat dijamin konstitusi, namun terikat pada kode etik pegawai negeri sipil untuk tidak memihak kepentingan politik praktis demi menjaga objektivitas pelayanan publik.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-6\\" data-soal-num=\\"6\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #6</span>\\n                <span class=\\"hk-soal-category-tag\\">TIU • Analogi Kata Hubungan Fungsi & Sarana</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-6\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">STETOSKOP : DOKTER = ... : ...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-6\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">PENA : TINTA</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">CANGKUL : PETANI</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">PASIEN : RUMAH SAKIT</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">TERMOMETER : SUHU</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">RESEP : APOTEKER</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-6\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-6\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-6\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Hubungan analogi alat kerja utama terhadap profesinya: Stetoskop adalah alat kerja khas yang digunakan oleh Dokter saat bertugas, sebagaimana Cangkul adalah alat kerja khas yang digunakan oleh Petani di sawah.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-7\\" data-soal-num=\\"7\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #7</span>\\n                <span class=\\"hk-soal-category-tag\\">TIU • Silogisme Logika 3 Premis</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-7\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Premis 1: Semua pelamar yang lolos seleksi SKD CPNS wajib mengikuti tes SKB.<br>Premis 2: Sebagian pelamar yang mengikuti tes SKB memiliki sertifikat pendidik (serdik).<br>Kesimpulan yang paling sah secara logika adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-7\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Semua pelamar yang memiliki serdik pasti lolos tes SKD.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Sebagian pelamar yang lolos seleksi SKD CPNS memiliki sertifikat pendidik (serdik).</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Semua pelamar yang mengikuti tes SKB pasti diterima menjadi ASN.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Pelamar yang tidak memiliki serdik tidak boleh mengikuti tes SKD.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Tidak ada pelamar yang lolos SKD yang memiliki serdik.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-7\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-7\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-7\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Menggunakan aturan silogisme partikular (sebagian): Jika Semua A adalah B, dan Sebagian B adalah C, maka kesimpulannya Sebagian A adalah C. Dalam konteks ini: Sebagian pelamar yang lolos seleksi SKD (A) memiliki sertifikat pendidik (C).</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-8\\" data-soal-num=\\"8\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #8</span>\\n                <span class=\\"hk-soal-category-tag\\">TIU • Deret Angka Bertingkat Kombinasi</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-8\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Tentukan angka berikutnya dari deret angka berikut:<br><strong>4, 7, 13, 25, 49, ...?</strong></div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-8\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">75</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">87</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">97</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">99</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">102</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-8\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-8\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-8\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Analisis selisih deret:<br>4 ke 7 selisih +3<br>7 ke 13 selisih +6 (+3 x 2)<br>13 ke 25 selisih +12 (+6 x 2)<br>25 ke 49 selisih +24 (+12 x 2)<br>Maka selisih berikutnya adalah +24 x 2 = +48.<br>Angka berikutnya: 49 + 48 = <strong>97</strong>. (Atau pola $2n - 1$: $4 \\\\times 2 - 1 = 7$, $7 \\\\times 2 - 1 = 13$, $13 \\\\times 2 - 1 = 25$, $25 \\\\times 2 - 1 = 49$, $49 \\\\times 2 - 1 = 97$).</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-9\\" data-soal-num=\\"9\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #9</span>\\n                <span class=\\"hk-soal-category-tag\\">TIU • Soal Cerita Aljabar & Kecepatan</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-9\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Budi berkendara mobil dari Kota A ke Kota B dengan kecepatan rata-rata 60 km/jam pada pukul 08.00 WIB. Pada saat yang sama, Doni berkendara dari Kota B menuju Kota A melalui jalur yang sama dengan kecepatan rata-rata 80 km/jam. Jika jarak Kota A dan Kota B adalah 280 km, pada pukul berapakah mereka akan berpapasan di jalan?</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-9\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">09.30 WIB</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">10.00 WIB</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">10.15 WIB</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">10.30 WIB</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">11.00 WIB</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-9\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-9\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-9\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Rumus waktu berpapasan ($t$):<br>$t = \\\\frac{\\\\text{Jarak Total}}{V_1 + V_2} = \\\\frac{280}{60 + 80} = \\\\frac{280}{140} = 2 \\\\text{ jam}$.<br>Karena mereka berangkat bersamaan pukul 08.00 WIB, maka mereka akan berpapasan pada pukul: $08.00 + 02.00 = \\\\mathbf{10.00 \\\\text{ WIB}}$.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-10\\" data-soal-num=\\"10\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #10</span>\\n                <span class=\\"hk-soal-category-tag\\">TIU • Penalaran Analitis Urutan & Jadwal</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-10\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Enam orang calon pegawai (A, B, C, D, E, dan F) diwawancarai secara berurutan dalam satu hari kerja:<br>1. D diwawancarai tepat setelah B.<br>2. A diwawancarai sebelum C.<br>3. E diwawancarai pada urutan pertama.<br>4. F diwawancarai tepat sebelum B.<br>Jika C diwawancarai pada urutan terakhir (ke-6), maka siapa yang diwawancarai pada urutan ke-4?</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-10\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">A</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">B</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">D</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">F</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">C</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-10\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-10\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-10\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Urutan 1 = E, Urutan 6 = C. Blok berturutan: F tepat sebelum B, dan D tepat setelah B -> [F, B, D]. Sisa slot untuk A dan [F, B, D] adalah slot 2, 3, 4, 5. Susunan yang tepat: Urutan 1: E, Urutan 2: A, Urutan 3: F, <strong>Urutan 4: B</strong>, Urutan 5: D, Urutan 6: C.<br>Kandidat pada urutan ke-4 adalah <strong>B</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n            <h2 id=\\"kesimpulan\\">5. Kesimpulan &amp; Rekomendasi Belajar Harian</h2>\\n            <p>Konsistensi adalah kunci utama keberhasilan menembus formasi ASN. Luangkan waktu minimal <strong>90 menit setiap hari</strong> untuk mengerjakan minimal 50 latihan soal dengan batas waktu stopwatch. Evaluasi setiap kesalahan pada lembar pembahasan untuk membangun insting eliminasi opsi yang tajam saat hari ujian sesungguhnya.</p>\\n        "}, {"key": "cv", "title": "Panduan Lengkap Membuat CV ATS Friendly Bahasa Indonesia (+ Free Template Word & PDF)", "category": "CV & Berkas", "tags": ["CV ATS Friendly", "Resume Kerja", "Surat Lamaran", "Fresh Graduate", "Template CV"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Catatan Penting:</strong> Lebih dari 75% CV pelamar kerja di perusahaan multinasional, BUMN, dan korporasi terkemuka otomatis tersaring oleh sistem <em>Applicant Tracking System</em> (ATS) sebelum pernah dibaca oleh rekruter manusia. Pelajari panduan praktis ini untuk memastikan resume Anda tembus screening awal 100%.\\n            </div>\\n\\n            <h2 id=\\"apa-itu-ats\\">1. Apa itu Sistem ATS &amp; Bagaimana Cara Kerjanya?</h2>\\n            <p><strong>Applicant Tracking System (ATS)</strong> adalah perangkat lunak manajemen rekrutmen yang digunakan HRD untuk menyaring, mengindeks, dan memeringkat ribuan berkas lamaran kerja secara otomatis. Sistem ini bekerja dengan menggunakan algoritma <em>parsing</em> teks:</p>\\n            <ul>\\n                <li>Bot ATS membaca file resume Anda dari kiri ke kanan, atas ke bawah.</li>\\n                <li>Bot memindai kata kunci (<em>keywords</em>) penting seperti jabatan, nama software, bahasa pemrograman, sertifikasi, dan keterampilan spesifik.</li>\\n                <li>Sistem memberikan skor kecocokan (<em>match rate percentage</em>) antara resume Anda dengan kriteria yang diminta pada iklan lowongan kerja.</li>\\n            </ul>\\n\\n            <h2 id=\\"kesalahan-fatal\\">2. 7 Kesalahan Fatal yang Menggugurkan CV di Sistem ATS</h2>\\n            <ol>\\n                <li><strong>Menggunakan Layout Multi-Kolom Rumit</strong>: Layout dua kolom atau tiga kolom sering dibaca secara acak dan teracak oleh parser bot, sehingga pengalaman kerja Anda bisa tertukar dengan riwayat hobi.</li>\\n                <li><strong>Menyisipkan Grafik Rating Keahlian</strong>: Grafik batang (progress bar 80%) atau rating bintang 4/5 tidak memiliki arti semantik teks bagi bot ATS dan justru memakan ruang berharga.</li>\\n                <li><strong>Menempatkan Teks di Dalam Text Box Mengambang</strong>: Kotak teks (*text box*) di Microsoft Word sering diabaikan total oleh parser ATS sehingga seluruh teks di dalamnya dianggap kosong.</li>\\n                <li><strong>Menggunakan Font Kaligrafi / Dekoratif</strong>: Font non-standar sering berubah menjadi karakter aneh atau kotak-kotak (*tofu*) pada sistem pembaca teks.</li>\\n                <li><strong>Menaruh Kontak di Header / Footer Word</strong>: Beberapa software ATS lama tidak membaca area header dan footer margin dokumen. Pastikan kontak berada di badan utama teks.</li>\\n                <li><strong>Format File yang Salah</strong>: Mengirim format JPG/PNG adalah jaminan 100% gagal screening. Selalu gunakan format <strong>.docx</strong> atau <strong>PDF teks</strong> (bukan scan PDF).</li>\\n                <li><strong>Tidak Menyesuaikan Kata Kunci</strong>: Mengirimkan satu CV yang sama persis untuk 50 jenis lowongan berbeda tanpa menyelaraskan istilah kualifikasi loker.</li>\\n            </ol>\\n\\n            <h2 id=\\"struktur-anatomi\\">3. Struktur Anatomi Ideal Resume ATS Bahasa Indonesia</h2>\\n            <p>Susunlah resume Anda dalam format satu kolom kronologis terbalik (*Reverse Chronological*) dengan urutan baku berikut:</p>\\n            <ol>\\n                <li><strong>Header Kontak</strong>: Nama Lengkap (Bold, 18-20pt), Nomor WhatsApp (+62), Email Profesional, Tautan Profil LinkedIn, Kota Domisili (cukup: Kota, Provinsi). <em>Tidak perlu mencantumkan agama, status pernikahan, atau alamat lengkap RT/RW.</em></li>\\n                <li><strong>Ringkasan Profesional (*Professional Summary*)</strong>: 3-4 kalimat padat yang merangkum posisi keahlian Anda, jumlah tahun pengalaman kerja, dan pencapaian angka terbesar.</li>\\n                <li><strong>Pengalaman Kerja (*Work Experience*)</strong>: Dari yang paling baru ke yang paling lama. Tuliskan Jabatan, Nama Perusahaan, Lokasi Kota, dan Periode Kerja (Bulan Tahun – Bulan Tahun).</li>\\n                <li><strong>Riwayat Pendidikan (*Education*)</strong>: Gelar, Jurusan, Nama Universitas, Kota, Tahun Kelulusan, dan Nilai IPK (jika di atas 3.25).</li>\\n                <li><strong>Keahlian (*Skills*)</strong>: Hard skills teknis (software/tools) dan soft skills profesional.</li>\\n                <li><strong>Sertifikasi &amp; Pelatihan (*Certifications*)</strong>: Nama Sertifikat, Lembaga Penerbit, dan Tahun Terbit.</li>\\n            </ol>\\n\\n            <h2 id=\\"formula-star\\">4. Menulis Deskripsi Pengalaman dengan Formula Google XYZ / STAR</h2>\\n            <p>Hindari menuliskan sekadar daftar tugas harian pasif seperti: <em>\\"Bertanggung jawab mengelola media sosial\\"</em>. Ubah menjadi kalimat aktif berbasis pencapaian metrik angka:</p>\\n            <div class=\\"hk-callout-box\\">\\n                <strong>Rumus Google:</strong> <em>\\"Berhasil mencapai [X], yang diukur dengan metrik [Y], melalui tindakan nyata [Z].\\"</em><br><br>\\n                <strong>❌ Contoh Pasif:</strong> Mengelola akun Instagram perusahaan dan membuat konten mingguan.<br>\\n                <strong>✅ Contoh Standar ATS:</strong> Meningkatkan jumlah pengikut Instagram organik sebesar 45% dalam 4 bulan dan menaikkan tingkat interaksi (engagement rate) dari 1.8% menjadi 4.2% melalui eksekusi 20 video edukatif berdurasi pendek.\\n            </div>\\n\\n            <h2 id=\\"format-teknis\\">5. Rekomendasi Font, Spasi, Margin &amp; Format Dokumen</h2>\\n            <ul>\\n                <li><strong>Pilihan Font Standar</strong>: Calibri, Arial, Helvetica, Georgia, atau Roboto.</li>\\n                <li><strong>Ukuran Font</strong>: 10 - 11pt untuk paragraf isi, 12 - 14pt untuk judul sub-bab (Bold), 18 - 20pt untuk nama pelamar di bagian teratas.</li>\\n                <li><strong>Margin Dokumen</strong>: 1 inci (2.54 cm) pada semua sisi (Top, Bottom, Left, Right).</li>\\n                <li><strong>Spasi Baris</strong>: 1.15 dengan spasi antar paragraf 4-6pt.</li>\\n                <li><strong>Panjang Resume</strong>: 1 halaman untuk fresh graduate hingga 3 tahun pengalaman; maksimal 2 halaman untuk profesional senior di atas 5 tahun pengalaman.</li>\\n            </ul>\\n\\n            <h2 id=\\"template-teks\\">6. Template Teks Utuh Siap Edit (Copy-Paste)</h2>\\n            <p>Salin teks di bawah ini ke Microsoft Word atau Google Docs Anda dan sesuaikan dengan data riwayat Anda:</p>\\n\\n            <div class=\\"hk-template-wrapper\\"><div class=\\"hk-template-header\\"><span class=\\"hk-template-badge\\">📋 Template Resume &amp; CV ATS Bahasa Indonesia</span><button type=\\"button\\" class=\\"hk-btn-copy-template\\" aria-label=\\"Salin Template CV\\"><svg width=\\"15\\" height=\\"15\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2\\"><rect x=\\"9\\" y=\\"9\\" width=\\"13\\" height=\\"13\\" rx=\\"2\\" ry=\\"2\\"></rect><path d=\\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\\"></path></svg> <span>Salin Template CV</span></button></div><div class=\\"hk-template-display-box\\">NAMA LENGKAP PELAMAR\\nKota Bandar Lampung, Lampung | +62 812-3456-7890 | nama.email@gmail.com | linkedin.com/in/namaprofil\\n\\nRINGKASAN PROFESIONAL\\nProfesional Digital Marketing berpengalaman 2+ tahun dalam mengelola kampanye iklan berbayar (Meta Ads, Google Ads) dan optimasi SEO website e-commerce. Terbukti berhasil meningkatkan omzet penjualan digital sebesar 38% dalam waktu 6 bulan dengan efisiensi biaya akuisisi pelanggan (CAC) turun 18%. Memiliki sertifikasi resmi Google Digital Garage dan BNSP Digital Marketing.\\n\\nPENGALAMAN KERJA\\nDigital Marketing Specialist | PT Inovasi Niaga Digital, Jakarta Selatan (Remote)\\nMaret 2024 – Sekarang\\n• Merancang dan mengeksekusi strategi iklan berbayar Meta Ads & Google Search Ads dengan anggaran Rp 35.000.000 per bulan, menghasilkan ROAS rata-rata 4.8x.\\n• Mengembangkan 15 artikel pilar SEO ramah mesin pencari yang berhasil menembus halaman pertama Google, meningkatkan traffic organik website dari 12.000 menjadi 45.000 kunjungan bulanan.\\n• Berkolaborasi bersama tim kreatif dan copywriting untuk memproduksi konten visual yang menaikkan CTR (Click-Through Rate) kampanye promosi dari 1.2% menjadi 3.4%.\\n\\nSocial Media Officer | CV Kreasi Media Mandiri, Bandar Lampung\\nJanuari 2023 – Februari 2024\\n• Mengelola jadwal publikasi konten Instagram dan TikTok dengan rata-rata 5 konten per minggu, menumbuhkan audiens dari 8.000 menjadi 28.000 followers dalam tempo 1 tahun.\\n• Menangani interaksi customer relation via Direct Message (DM) dan WhatsApp Business dengan waktu respons rata-rata di bawah 5 menit dan tingkat kepuasan pelanggan 96%.\\n\\nRIWAYAT PENDIDIKAN\\nSarjana Ilmu Komunikasi (S.I.Kom) | Universitas Lampung (UNILA)\\nTahun Kelulusan: 2022 | IPK: 3.72 / 4.00 (Predikat Pujian / Cumlaude)\\n\\nKEAHLIAN TEKNIS & BAHASA\\n• Hard Skills: Search Engine Optimization (SEO), Meta Ads Manager, Google Analytics 4 (GA4), WordPress CMS, Canva Pro, Copywriting.\\n• Soft Skills: Negosiasi, Analisis Data Metrik, Komunikasi Antar Divisi, Manajemen Waktu.\\n• Bahasa: Bahasa Indonesia (Penutur Asli), Bahasa Inggris (Skor TOEFL ITP 540).\\n\\nSERTIFIKASI PROFESI\\n• Sertifikasi Profesi Digital Marketing Specialist – BNSP (Tahun 2024)\\n• Google Ads Search Certification – Google Skillshop (Tahun 2023)</div></div>\\n        "}, {"key": "psikotes", "title": "Cara Mengerjakan Tes Koran (Kraepelin & Pauli) Agar Skor Tinggi & Grafik Stabil (10 Latihan & Trik)", "category": "Psikotes Kerja", "tags": ["Tes Kraepelin", "Tes Pauli", "Psikotes Kerja", "Tes Koran", "Ujian Psikologi"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Fakta Penting:</strong> Tes koran bukan ujian kepintaran matematika. Banyak sarjana teknik dan matematika justru gagal karena tidak memahami bahwa tes ini dirancang untuk membaca ritme kerja bawah sadar, daya tahan kelelahan, dan stabilitas emosi di bawah tekanan instruksi berulang.\\n            </div>\\n\\n            <h2 id=\\"tujuan-psikotes\\">1. Apa yang Sebenarnya Dinilai Psikolog dalam Tes Koran?</h2>\\n            <p>Tes Kraepelin dan Pauli mengukur 4 parameter profil psikologis kerja utama:</p>\\n            <ul>\\n                <li><strong>Kecepatan Kerja (*Tempo Kerja*)</strong>: Dinilai dari jumlah angka yang berhasil Anda jumlahkan per kolom. Menunjukkan apakah Anda tipe pekerja lambat, sedang, atau gesit.</li>\\n                <li><strong>Ketelitian Kerja (*Akurasi*)</strong>: Dinilai dari seberapa sedikit kesalahan hitung atau angka yang terlewati. Menunjukkan tingkat kecermatan saat mengerjakan tugas rutin.</li>\\n                <li><strong>Ketahanan Kerja (*Kestabilan*)</strong>: Dinilai dari konsistensi tinggi grafik dari kolom pertama hingga kolom terakhir. Menunjukkan ketahanan fisik dan daya tahan stres.</li>\\n                <li><strong>Pengendalian Emosi (*Emotional Stability*)</strong>: Dinilai dari fluktuasi grafik. Grafik yang naik turun tajam menandakan individu yang mudah panik atau moody.</li>\\n            </ul>\\n\\n            <h2 id=\\"beda-kraepelin-pauli\\">2. Perbedaan Fundamental Kraepelin vs Pauli</h2>\\n            <table style=\\"width:100%; border-collapse:collapse; margin:20px 0; font-size:13.5px;\\">\\n                <thead>\\n                    <tr style=\\"background:#f1f5f9; border-bottom:2px solid #cbd5e1;\\">\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Parameter</th>\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Tes Kraepelin</th>\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Tes Pauli (Koran)</th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Arah Penjumlahan</td>\\n                        <td style=\\"padding:10px 14px;\\">Dari Bawah ke Atas</td>\\n                        <td style=\\"padding:10px 14px;\\">Dari Atas ke Bawah</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Ukuran Lembar</td>\\n                        <td style=\\"padding:10px 14px;\\">Kertas ukuran A4 / Folio (50 kolom)</td>\\n                        <td style=\\"padding:10px 14px;\\">Kertas koran lebar raksasa</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Instruksi Pindah</td>\\n                        <td style=\\"padding:10px 14px;\\">Instruksi: \\"PINDAH!\\" setiap 15-30 detik</td>\\n                        <td style=\\"padding:10px 14px;\\">Instruksi: \\"GARIS!\\" setiap beberapa menit</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Total Waktu Ujian</td>\\n                        <td style=\\"padding:10px 14px;\\">Singkat: sekitar 15 - 20 menit</td>\\n                        <td style=\\"padding:10px 14px;\\">Sangat lama: 60 menit penuh tanpa henti</td>\\n                    </tr>\\n                </tbody>\\n            </table>\\n\\n            <h2 id=\\"4-grafik\\">3. 4 Bentuk Grafik Hasil Tes &amp; Maknanya bagi Rekruter</h2>\\n            <ol>\\n                <li><strong>Grafik Menurun (*Desenden*)</strong>: Jumlah angka di kolom awal sangat tinggi, lalu merosot drastis di pertengahan hingga akhir. <em>Arti Psikologis:</em> Tipe pelari cepat yang tidak punya stamina; cepat lelah dan mudah kehilangan fokus saat menghadapi pekerjaan panjang. <strong>(Potensi Gagal Tinggi)</strong>.</li>\\n                <li><strong>Grafik Zig-Zag Ekstrem (*Fluktuatif*)</strong>: Naik turun tajam tak berpola. <em>Arti Psikologis:</em> Suasana hati tidak stabil, mudah terdistraksi oleh lingkungan, dan rentan melakukan kesalahan saat berada di bawah tekanan deadline. <strong>(Kurang Disukai)</strong>.</li>\\n                <li><strong>Grafik Rata Datar (*Konstan*)</strong>: Garis horizontal stabil dari awal sampai akhir. <em>Arti Psikologis:</em> Disiplin, dapat diandalkan, namun cenderung bermain aman dan kurang berinisiatif mengambil tantangan lebih. <strong>(Cukup Baik)</strong>.</li>\\n                <li><strong>Grafik Menanjak Stabil (*Asenden Moderat*)</strong>: Garis grafik naik secara bertahap dan konsisten. <em>Arti Psikologis:</em> Memiliki adaptasi kerja yang sangat prima, semakin lama bekerja semakin fokus, berdaya tahan tinggi, dan mampu meningkatkan performa seiring waktu. <strong>(Sangat Direkomendasikan / Lolos)</strong>.</li>\\n            </ol>\\n\\n            <h2 id=\\"trik-fisik-mental\\">4. 7 Trik Rahasia Menjaga Ketahanan Fisik &amp; Mental</h2>\\n            <ul>\\n                <li><strong>Jangan Terpancing Peserta Lain</strong>: Bunyi desiran pensil peserta di sebelah Anda yang membalik halaman bukan berarti mereka lebih benar. Fokus pada lembar Anda sendiri.</li>\\n                <li><strong>Teknik Pensil 2B Berkualitas</strong>: Siapkan minimal 3 batang pensil 2B yang telah diraut runcing. Jangan gunakan pensil mekanik karena mata pensilnya mudah patah saat ditekan cepat.</li>\\n                <li><strong>Posisi Duduk Ergonomis</strong>: Duduk tegak dengan punggung menempel sandaran kursi, jarak mata sekitar 30 cm dari lembar kertas. Jangan membungkuk karena otot leher akan cepat kaku di menit ke-10.</li>\\n                <li><strong>Pernapasan Rileks</strong>: Gunakan pernapasan perut/diafragma yang teratur agar asupan oksigen ke otak tetap optimal.</li>\\n                <li><strong>Jangan Pernah Menghapus</strong>: Jika salah menuliskan angka, cukup coret satu garis pada angka yang salah dan tuliskan angka yang benar di samping kanannya. Menghapus dengan karet penghapus membuang waktu 4-5 detik yang berharga.</li>\\n            </ul>\\n\\n            <h2 id=\\"latihan-soal\\">5. 10 Latihan Soal Angka Koran &amp; Pola Logika Psikotes</h2>\\n            <p>Berikut adalah 10 butir soal latihan mencakup trik angka koran dan deret penalaran psikotes yang paling sering diujikan:</p>\\n\\n            \\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-1\\" data-soal-num=\\"1\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #1</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Deret • Pola Geometri Pecahan</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-1\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Berapakah nilai lanjutan dari deret berikut:<br><strong>64, 32, 16, 8, 4, ...?</strong></div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-1\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">3</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">2</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">1</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">0.5</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-1-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">0</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-1\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-1\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-1\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Pola pembagian konstan: setiap suku dibagi 2. $4 \\\\div 2 = 2$.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-2\\" data-soal-num=\\"2\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #2</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Deret • Pola Selisih Melompat</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-2\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Berapakah dua suku berikutnya dari deret:<br><strong>2, 3, 5, 8, 12, 17, ..., ...?</strong></div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-2\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">22, 28</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">23, 30</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">24, 31</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">23, 29</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-2-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">25, 32</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-2\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-2\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-2\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Pola penambahan selisih berurutan: +1, +2, +3, +4, +5, +6, +7.<br>$17 + 6 = 23$, dan $23 + 7 = 30$. Jawaban: <strong>23, 30</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-3\\" data-soal-num=\\"3\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #3</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Deret • Pola Angka Kembar Berseling</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-3\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Tentukan angka selanjutnya dari deret:<br><strong>5, 10, 7, 14, 11, 22, ...?</strong></div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-3\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">15</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">17</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">19</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">26</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-3-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">44</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-3\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-3\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-3\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Pola berseling: dikali 2, lalu dikurangi 3.<br>$5 \\\\times 2 = 10$, $10 - 3 = 7$, $7 \\\\times 2 = 14$, $14 - 3 = 11$, $11 \\\\times 2 = 22$, $22 - 3 = \\\\mathbf{19}$.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-4\\" data-soal-num=\\"4\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #4</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Angka Koran • Trik Digit Satuan</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-4\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Pada tes Pauli/Kraepelin, jika Anda menjumlahkan dua angka berturut-turut $8$ dan $9$, hasil penjumlahan adalah $17$. Angka yang wajib Anda tuliskan di lembar jawaban adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-4\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Tulis angka 17 lengkap</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Tulis angka 1 (angka puluhan)</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Tulis angka 7 (hanya angka satuan)</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Tulis angka 8</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-4-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Tulis angka 0</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-4\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-4\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-4\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Aturan baku tes koran internasional: jika hasil penjumlahan menghasilkan dua digit (10 ke atas), Anda hanya boleh menuliskan **angka satuan belakangnya saja**. Untuk $8 + 9 = 17$, maka yang ditulis adalah angka <strong>7</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-5\\" data-soal-num=\\"5\\" data-key=\\"A\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #5</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Angka Koran • Penjumlahan Puluhan</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-5\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Dalam lajur tes Pauli, Anda menjumpai deretan vertikal: 6, 4, 9, 3. Hasil penjumlahan bertahap dari atas ke bawah yang benar adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-5\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">0 (dari 6+4=10), lalu 3 (dari 4+9=13), lalu 2 (dari 9+3=12)</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">10, 13, 12</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">6, 4, 9</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">0, 4, 2</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-5-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">1, 1, 1</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-5\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-5\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-5\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: A</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Langkah per langkah:<br>1. $6 + 4 = 10 \\\\rightarrow$ tulis <strong>0</strong>.<br>2. $4 + 9 = 13 \\\\rightarrow$ tulis <strong>3</strong>.<br>3. $9 + 3 = 12 \\\\rightarrow$ tulis <strong>2</strong>.<br>Deret jawaban di antara spasi angka: <strong>0, 3, 2</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-6\\" data-soal-num=\\"6\\" data-key=\\"C\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #6</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Penalaran Figural • Rotasi Objek 90 Derajat</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-6\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Sebuah panah mengarah ke Atas (Utara). Kemudian berputar searah jarum jam sebesar 90°, lalu berputar lagi 180°, dan terakhir berputar berlawanan arah jarum jam sebesar 90°. Ke manakah arah panah sekarang?</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-6\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Utara</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Timur</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Selatan</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Barat</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-6-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Tenggara</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-6\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-6\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-6\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: C</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Total putaran = +90° + 180° - 90° = +180° dari posisi awal Utara, mengarah tepat ke arah sebaliknya, yaitu <strong>Selatan</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-7\\" data-soal-num=\\"7\\" data-key=\\"A\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #7</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Logika Aritmatika • Rasio Pekerja & Waktu</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-7\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Sebuah proyek gedung dapat diselesaikan oleh 15 pekerja dalam waktu 30 hari. Jika kontraktor ingin proyek tersebut selesai hanya dalam waktu 10 hari, berapakah jumlah pekerja tambahan yang harus direkrut?</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-7\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">30 orang</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">45 orang</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">15 orang</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">60 orang</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-7-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">25 orang</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-7\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-7\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-7\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: A</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Perbandingan berbalik nilai: $15 \\\\times 30 = X \\\\times 10 \\\\rightarrow X = 45 \\\\text{ pekerja total}$. Pekerja tambahan = $45 - 15 = \\\\mathbf{30 \\\\text{ orang}}$.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-8\\" data-soal-num=\\"8\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #8</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Logika Kata • Lawan Kata (Antonim)</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-8\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">ANTONIM dari kata: <strong>PASIF</strong> adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-8\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">STATIS</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">PROAKTIF</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">STABIL</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">NEGATIF</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-8-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">REAKTIF</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-8\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-8\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-8\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Pasif berarti tidak aktif, hanya menerima saja tanpa inisiatif. Lawan kata yang paling tepat adalah <strong>Proaktif</strong>.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-9\\" data-soal-num=\\"9\\" data-key=\\"D\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #9</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Analitis Logika • Kategori Benda Berbeda (Odd One Out)</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-9\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Manakah di antara kata berikut yang TIDAK termasuk dalam kelompoknya?</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-9\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">BCA</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">MANDIRI</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">BRI</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">BEI (Bursa Efek Indonesia)</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-9-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">BNI</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-9\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-9\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-9\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: D</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> BCA, Mandiri, BRI, dan BNI adalah lembaga perbankan komersial (Bank). Sedangkan BEI adalah penyelenggara pasar modal / bursa efek.</div>\\n        </div>\\n    </div>\\n    \\n\\n    <div class=\\"hk-interactive-soal\\" id=\\"soal-box-10\\" data-soal-num=\\"10\\" data-key=\\"B\\">\\n        <div class=\\"hk-soal-header\\">\\n            <div style=\\"display:flex; align-items:center; gap:8px;\\">\\n                <span class=\\"hk-soal-number-badge\\">Latihan Soal #10</span>\\n                <span class=\\"hk-soal-category-tag\\">Psikotes Kraepelin • Manajemen Emosi Saat Kelelahan</span>\\n            </div>\\n            <span class=\\"hk-soal-status-badge\\" id=\\"soal-status-10\\" style=\\"display:none; font-size:12px; font-weight:700;\\"></span>\\n        </div>\\n        <div class=\\"hk-soal-text\\">Ketika aba-aba \'Pindah!\' diteriakkan dan Anda baru menyelesaikan setengah kolom sedangkan peserta di samping Anda tampak jauh lebih cepat, respon psikologis paling efektif adalah...</div>\\n        <div class=\\"hk-soal-options-group\\" id=\\"options-group-10\\">\\n            <button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-A\\" data-letter=\\"A\\" >\\n            <span class=\\"hk-soal-opt-badge\\">A</span>\\n            <span class=\\"hk-soal-opt-label\\">Panik dan langsung mempercepat tulisan tanpa memperhatikan keakuratan penjumlahan.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-B\\" data-letter=\\"B\\" >\\n            <span class=\\"hk-soal-opt-badge\\">B</span>\\n            <span class=\\"hk-soal-opt-label\\">Tetap tenang, langsung pindah ke kolom baru tanpa menoleh ke kolom sebelumnya, dan mempertahankan ritme stabil sesuai kemampuan diri sendiri.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-C\\" data-letter=\\"C\\" >\\n            <span class=\\"hk-soal-opt-badge\\">C</span>\\n            <span class=\\"hk-soal-opt-label\\">Berhenti mengerjakan dan menunggu sesi istirahat.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-D\\" data-letter=\\"D\\" >\\n            <span class=\\"hk-soal-opt-badge\\">D</span>\\n            <span class=\\"hk-soal-opt-label\\">Mencoba menyontek kolom jawaban peserta di sebelah.</span>\\n        </button>\\n<button type=\\"button\\" class=\\"hk-soal-opt-btn\\" id=\\"opt-btn-10-E\\" data-letter=\\"E\\" >\\n            <span class=\\"hk-soal-opt-badge\\">E</span>\\n            <span class=\\"hk-soal-opt-label\\">Mengisi jawaban secara acak di baris tersisa pada kolom sebelumnya.</span>\\n        </button>\\n        </div>\\n        <div class=\\"hk-soal-action-row\\" style=\\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:14px;\\">\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-primary hk-btn-sm\\" id=\\"btn-check-10\\"  disabled>\\n                Periksa Jawaban\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-soal-toggle-btn\\" id=\\"btn-toggle-10\\" >\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\"><circle cx=\\"12\\" cy=\\"12\\" r=\\"10\\"></circle><polyline points=\\"12 16 12 12 12 8\\"></polyline></svg>\\n                <span>Kunci &amp; Pembahasan</span>\\n            </button>\\n            <button type=\\"button\\" class=\\"hk-btn hk-btn-subtle hk-btn-sm\\"  style=\\"margin-left:auto;\\">\\n                Ulangi Soal\\n            </button>\\n        </div>\\n        <div class=\\"hk-soal-explanation is-hidden\\" id=\\"exp-10\\">\\n            <span class=\\"hk-soal-kunci-badge\\">Kunci Jawaban Resmi: B</span>\\n            <div style=\\"margin-top: 6px; font-size:13.5px; line-height:1.65;\\"><strong>Pembahasan:</strong> Karakteristik yang dinilai psikolog dalam tes koran adalah ketahanan terhadap tekanan (*resilience*) dan fokus internal. Memaksakan diri mengejar kecepatan orang lain akan merusak akurasi dan menciptakan grafik zigzag ekstrem yang berujung pada penilaian ketidakstabilan emosional.</div>\\n        </div>\\n    </div>\\n    \\n        "}, {"key": "interview", "title": "20 Pertanyaan Interview HRD Paling Sering Muncul & Cara Menjawab dengan Metode STAR", "category": "Wawancara Kerja", "tags": ["Interview HRD", "Metode STAR", "Negosiasi Gaji", "Wawancara User", "Tips Lolos Kerja"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Rahasia Wawancara:</strong> Wawancara kerja bukan ajang interogasi menguji hafalan, melainkan dialog bisnis dua arah untuk mencocokkan apakah kepribadian dan keahlian Anda dapat menyelesaikan masalah perusahaan. Kuasai <strong>Metode STAR</strong> untuk menjawab setiap pertanyaan berbasis perilaku dengan percaya diri.\\n            </div>\\n\\n            <h2 id=\\"metode-star\\">1. Konsep &amp; Rumus Metode STAR (Situation, Task, Action, Result)</h2>\\n            <p>Metode STAR adalah teknik teruji secara internasional untuk merespons pertanyaan wawancara berbasis perilaku (*Behavioral Interview Questions*):</p>\\n            <ul>\\n                <li><strong>Situation (Situasi - 15% waktu)</strong>: Gambarkan latar belakang masalah atau tantangan spesifik yang pernah Anda hadapi di masa lalu. Buatlah ringkas dan berkonteks jelas.</li>\\n                <li><strong>Task (Tugas - 15% waktu)</strong>: Jelaskan tanggung jawab spesifik apa yang harus Anda selesaikan dalam situasi tersebut.</li>\\n                <li><strong>Action (Aksi Nyata - 50% waktu)</strong>: Ini adalah bagian paling penting. Uraikan langkah konkret apa yang <em>Anda sendiri</em> ambil untuk mengatasi masalah tersebut. Gunakan kata \\"Saya\\" (bukan hanya \\"Kami\\").</li>\\n                <li><strong>Result (Hasil Akhir - 20% waktu)</strong>: Paparkan hasil positif yang dicapai. Sertakan data angka atau metrik kuantitatif (contoh: efisiensi waktu 30%, kenaikan omzet 20%, atau penghargaan dari atasan).</li>\\n            </ul>\\n\\n            <h2 id=\\"etika-bahasa-tubuh\\">2. Bahasa Tubuh &amp; Etika Wawancara Offline vs Online</h2>\\n            <ul>\\n                <li><strong>Wawancara Tatap Muka (Offline)</strong>: Jabat tangan tegas (firm handshake), tersenyum hangat, tatap mata pewawancara (eye contact) secara wajar tanpa melotot, dan letakkan kedua tangan di atas paha atau meja dengan santai tanpa melipat tangan di dada.</li>\\n                <li><strong>Wawancara Daring (Online via Zoom / GMeet)</strong>: Posisikan kamera sejajar dengan mata (eye level), pastikan pencahayaan terang dari arah depan (bukan backlight), gunakan mikrofon/headset jernih, dan lihat langsung ke lensa webcam saat Anda sedang berbicara (bukan melihat gambar diri sendiri di layar).</li>\\n            </ul>\\n\\n            <h2 id=\\"10-pertanyaan\\">3. 10 Pertanyaan Wawancara Inti Beserta Contoh Jawaban Sempurna</h2>\\n            <p>Berikut adalah 10 pertanyaan wawancara paling sering muncul di perusahaan BUMN, multinasional, dan swasta lengkap dengan jebakan yang harus dihindari serta contoh jawaban terbaik:</p>\\n\\n            \\n    <div class=\\"hk-soal-box\\" id=\\"interview-1\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 1: \'Ceritakan tentang diri Anda!\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Pembuka (Ice Breaking & Elevator Pitch)</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menceritakan riwayat hidup dari SD atau menyebutkan hobi yang tidak relevan dengan pekerjaan.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Gunakan rumus <strong>Present (Masa Kini) &rarr; Past (Masa Lalu) &rarr; Future (Masa Depan)</strong> dalam waktu 90 detik:\\n<div class=\\"hk-template-display-box\\">\\"Terima kasih atas kesempatannya Bapak/Ibu. Saat ini saya adalah seorang fresh graduate S1 Manajemen Bisnis dari Universitas Lampung dengan fokus pada Manajemen Sumber Daya Manusia dan operasional bisnis. \\n\\nSelama masa perkuliahan, saya aktif memimpin divisi rekrutmen organisasi mahasiswa di mana saya mengelola seleksi lebih dari 150 pendaftar. Saya juga telah menyelesaikan magang di PT XYZ sebagai HR Assistant selama 6 bulan, di mana saya berhasil mempercepat proses screening awal berkas pelamar sebesar 25% menggunakan template evaluasi baru.\\n\\nSaya sangat antusias dengan posisi HR Officer di perusahaan ini karena reputasi perusahaan dalam budaya kerja kolaboratif dan saya ingin mendedikasikan kemampuan analisis talenta saya untuk memajukan divisi SDM perusahaan.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-2\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 2: \'Apa kelebihan terbesar Anda?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Kekuatan Diri (Self-Awareness & Value Proposition)</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menyebutkan klaim klise tanpa bukti: \'Saya orangnya pekerja keras dan jujur\'.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Sebutkan keahlian spesifik yang selaras dengan kualifikasi loker, lalu sertakan contoh proyek nyata:\\n<div class=\\"hk-template-display-box\\">\\"Kelebihan utama saya adalah ketelitian data dan pemecahan masalah secara analitis. Ketika menangani laporan audit persediaan di tempat magang sebelumnya, saya menemukan selisih pencatatan stok senilai puluhan juta rupiah yang terlewatkan selama 2 bulan. Saya membuat formula rekonsiliasi otomatis di spreadsheet yang memangkas waktu pengecekan bulanan dari 3 hari menjadi 4 jam saja.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-3\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 3: \'Apa kelemahan terbesar Anda?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Kejujuran & Upaya Perbaikan</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Mengaku tidak punya kelemahan, atau memberi kelemahan palsu: \'Saya terlalu perfeksionis\'.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Pilih kelemahan profesional yang nyata, namun bukan kualifikasi inti pekerjaan, lalu jelaskan langkah konkret yang sedang Anda ambil untuk mengatasinya:\\n<div class=\\"hk-template-display-box\\">\\"Di masa lalu, saya cenderung merasa cemas ketika harus melakukan presentasi spontan di depan forum besar tanpa persiapan panjang. Untuk memperbaiki hal tersebut, dalam 6 bulan terakhir saya aktif bergabung dengan klub public speaking Toastmasters dan secara sukarela mengambil peran sebagai juru bicara kelompok proyek. Langkah ini membantu saya jauh lebih tenang dan percaya diri dalam menyampaikan gagasan secara terstruktur.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-4\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 4: \'Mengapa Anda tertarik bekerja di perusahaan kami?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Riset & Keselarasan Motivasi</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menjawab karena ingin cari pengalaman, atau karena lokasinya dekat rumah.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Tunjukkan bahwa Anda telah meriset produk, inovasi, atau prestasi perusahaan:\\n<div class=\\"hk-template-display-box\\">\\"Saya telah mengikuti perkembangan perusahaan ini sejak meluncurkan inisiatif digitalisasi logistik tahun lalu. Saya sangat mengagumi komitmen perusahaan terhadap efisiensi rantai pasok dan keberlanjutan lingkungan. Berbekal latar belakang saya di bidang supply chain dan sertifikasi manajemen logistik, saya ingin terlibat langsung dalam mengoptimalkan jalur distribusi regional perusahaan di area Sumatera.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-5\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 5: \'Ceritakan situasi saat Anda menghadapi kegagalan atau tekanan kerja berat!\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Behavioral Question (Wajib Metode STAR)</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menyalahkan orang lain atau rekan satu tim atas kegagalan tersebut.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Gunakan metode STAR (Situation, Task, Action, Result):\\n<div class=\\"hk-template-display-box\\">\\"<strong>Situation:</strong> Pada proyek peluncuran aplikasi mobile kampus, kami menghadapi kemunduran jadwal 2 minggu karena dua programmer utama jatuh sakit.\\n<strong>Task:</strong> Sebagai koordinator proyek, saya bertanggung jawab memastikan aplikasi tetap meluncur sesuai jadwal pendaftaran mahasiswa baru.\\n<strong>Action:</strong> Saya segera mengaudit sisa fitur, membagi beban kerja secara modular, dan memprioritaskan fitur minimum viable product (MVP) yang paling krusial. Saya juga turun tangan langsung melakukan QA testing setiap malam.\\n<strong>Result:</strong> Aplikasi berhasil dirilis tepat waktu dengan tingkat kepuasan pengguna 94% dan fitur pelengkap kami luncurkan bertahap di update patch berikutnya.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-6\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 6: \'Bagaimana Anda menghadapi rekan kerja yang tidak kooperatif?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Kerjasama Tim & Manajemen Konflik</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menghindari rekan tersebut atau langsung mengadu ke atasan.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Tunjukkan kedewasaan komunikasi dan empati profesional:\\n<div class=\\"hk-template-display-box\\">\\"Saya selalu mengutamakan komunikasi personal empatik terlebih dahulu. Saya akan mengajak rekan kerja tersebut berdiskusi empat mata untuk memahami kendala yang sedang dihadapinya, apakah ada hambatan teknis atau beban kerja yang tidak seimbang. Kemudian kami menyepakati batas tanggung jawab masing-masing secara tertulis agar selaras dengan target divisi tanpa menimbulkan gesekan emosional.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-7\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 7: \'Mengapa Anda berhenti dari pekerjaan Anda sebelumnya?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Integritas & Loyalitas</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Membicarakan keburukan mantan atasan, gaji kecil, atau gosip kantor.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Fokuskan pada dorongan mencari tantangan baru dan pertumbuhan profesional:\\n<div class=\\"hk-template-display-box\\">\\"Saya sangat bersyukur atas pengalaman dan ilmu yang saya peroleh selama 2 tahun di perusahaan sebelumnya. Namun saat ini saya merasa siap untuk mengambil tanggung jawab yang lebih luas di skala operasional yang lebih besar, dan profil posisi di perusahaan Bapak/Ibu menawarkan ruang pertumbuhan karir yang sangat selaras dengan tujuan jangka panjang saya.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-8\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 8: \'Di mana Anda melihat diri Anda dalam 3 hingga 5 tahun ke depan?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Visi Karir & Stabilitas</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menjawab ingin punya bisnis sendiri tahun depan atau \'tidak tahu\'.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Tunjukkan komitmen jangka menengah yang selaras dengan jenjang karir perusahaan:\\n<div class=\\"hk-template-display-box\\">\\"Dalam 2 tahun pertama, fokus saya adalah menguasai seluruh alur operasional di posisi ini dan membuktikan performa kerja melampaui target KPI. Dalam 3 hingga 5 tahun ke depan, saya bercita-cita mengembangkan kompetensi kepemimpinan agar dapat memegang tanggung jawab sebagai Senior Specialist atau Team Lead yang mampu membimbing talenta-talenta baru di divisi ini.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-9\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 9: \'Berapa ekspektasi gaji Anda?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Negosiasi Kompensasi</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menjawab \'Terserah perusahaan\' atau meminta angka tanpa dasar riset.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Berikan rentang realistis berdasarkan riset upah pasar dan tanyakan paket benefit keseluruhan:\\n<div class=\\"hk-template-display-box\\">\\"Berdasarkan riset saya terhadap standar gaji posisi ini di wilayah setempat serta mempertimbangkan kualifikasi dan pengalaman yang saya miliki, ekspektasi saya berada di rentang Rp 5.500.000 hingga Rp 7.000.000 per bulan. Namun saya tentu sangat fleksibel dan terbuka untuk mendiskusikan penawaran paket benefit, asuransi, dan peluang jenjang karir yang disediakan perusahaan.\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n    <div class=\\"hk-soal-box\\" id=\\"interview-10\\">\\n        <div class=\\"hk-soal-header\\">\\n            <span class=\\"hk-soal-number-badge\\">Pertanyaan 10: \'Apakah ada pertanyaan yang ingin Anda tanyakan kepada kami?\'</span>\\n            <span class=\\"hk-soal-category-tag\\">Pertanyaan Penutup Penentu (Wajib Bertanya)</span>\\n        </div>\\n        <div style=\\"background:#fff1f2; border:1px solid #fecdd3; border-radius:8px; padding:10px 14px; margin-bottom:12px; font-size:13px; color:#9f1239;\\">\\n            <strong>⚠️ Jebakan yang Harus Dihindari:</strong> Menjawab \'Tidak ada, sudah cukup jelas\'.\\n        </div>\\n        <div style=\\"font-size:14px; line-height:1.65; color:var(--hk-text-main);\\">\\n            <strong>✅ Panduan Jawaban Terbaik &amp; Contoh Naskah:</strong>\\n            <div style=\\"margin-top:8px;\\">Ajukan 2-3 pertanyaan berkualitas tinggi yang menunjukkan Anda serius dan antusias:\\n<div class=\\"hk-template-display-box\\">1. \\"Apa tolok ukur keberhasilan utama untuk orang yang mengisi posisi ini dalam 3 bulan pertama masa percobaan?\\"\\n2. \\"Bagaimana budaya kerja tim dalam menghadapi tantangan target yang ketat?\\"\\n3. \\"Apa tahapan selanjutnya dari proses rekrutmen ini dan kapan saya bisa mengantisipasi kabar berikutnya?\\"</div></div>\\n        </div>\\n    </div>\\n\\n\\n            <h2 id=\\"pertanyaan-balik\\">4. Trik Mengajukan Pertanyaan Balik ke HRD di Sesi Akhir</h2>\\n            <p>Ketika pewawancara bertanya: <em>\\"Apakah ada yang ingin Anda tanyakan kepada kami?\\"</em>, <strong>JANGAN PERNAH MENJAWAB \\"TIDAK ADA\\"</strong>. Tidak bertanya memberi kesan bahwa Anda tidak antusias atau pasif. Ajukan pertanyaan yang menggali ekspektasi posisi kerja tersebut untuk meninggalkan kesan profesional yang kuat.</p>\\n        "}, {"key": "k3", "title": "Panduan Lengkap Sertifikasi Ahli K3 Umum Kemenaker untuk Fresh Graduate & Profesional", "category": "Sertifikasi Profesi", "tags": ["Ahli K3 Umum", "Sertifikasi Kemenaker", "Sertifikasi Profesi"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Kenapa Sertifikat K3 Sangat Dicari?</strong> Berdasarkan UU No. 1 Tahun 1970 dan Permenaker No. 04/MEN/1987, setiap tempat kerja dengan lebih dari 100 karyawan atau memiliki potensi bahaya tinggi (konstruksi, manufaktur, migas, tambang, rumah sakit) <strong>wajib memiliki minimal satu Ahli K3 Umum bersertifikat resmi Kemenaker</strong>.\\n            </div>\\n\\n            <h2 id=\\"dasar-hukum\\">1. Landasan Hukum &amp; Pentingnya Ahli K3 Umum</h2>\\n            <p>Keselamatan dan Kesehatan Kerja (K3) adalah pilar mutlak operasional industri modern. Ahli K3 Umum ditunjuk oleh Menteri Ketenagakerjaan untuk mengawasi langsung ditaatinya peraturan perundang-undangan K3 di tempat kerja guna mencegah terjadinya kecelakaan kerja (*zero accident*) dan penyakit akibat kerja (PAK).</p>\\n\\n            <h2 id=\\"syarat-pelatihan\\">2. Persyaratan &amp; Alur Pembinaan 12 Hari</h2>\\n            <ol>\\n                <li><strong>Persyaratan Pendidikan</strong>: Minimal lulusan Diploma Tiga (D3) atau Sarjana (S1) dari semua jurusan teknik maupun non-teknik.</li>\\n                <li><strong>Alur Pembinaan</strong>: Melalui Perusahaan Jasa K3 (PJK3) resmi yang ditunjuk Kemnaker selama 12 hari kerja intensif (sekitar 120 jam pelajaran).</li>\\n                <li><strong>Tahapan Evaluasi</strong>: Ujian Pre-test & Post-test tertulis Kemenaker, observasi Praktik Kerja Lapangan (PKL) di pabrik/proyek nyata, penulisan laporan PKL, serta seminar sidang laporan di hadapan pengawas Kemnaker.</li>\\n            </ol>\\n\\n            <h2 id=\\"materi-modul\\">3. Materi Pokok Pembinaan Ahli K3 Umum</h2>\\n            <ul>\\n                <li>Kebijakan Nasional K3 dan Dasar-Dasar Keselamatan Kerja.</li>\\n                <li>K3 Mekanik, Pesawat Uap, Bejana Tekan, dan Tangki Timbun.</li>\\n                <li>K3 Instalasi Listrik dan Proteksi Kebakaran (APAR & Hydrant).</li>\\n                <li>K3 Konstruksi Bangunan dan Lingkungan Kerja (P3K & Higiene Industri).</li>\\n                <li>Manajemen Risiko (HIRADC / JSA) dan Investigasi Kecelakaan Kerja.</li>\\n                <li>Sistem Manajemen K3 (SMK3) berdasarkan Peraturan Pemerintah No. 50 Tahun 2012.</li>\\n            </ul>\\n\\n            <h2 id=\\"peluang-gaji\\">4. Peluang Karir &amp; Standar Gaji</h2>\\n            <p>Bagi lulusan baru (*fresh graduate*), memiliki lisensi Ahli K3 Umum Kemnaker melipatgandakan peluang panggilan kerja di posisi <em>HSE Officer, Safety Inspector, K3 Specialist, dan Compliance Officer</em> dengan rentang gaji awal Rp 5.000.000 hingga Rp 9.000.000 per bulan, dan mencapai belasan juta rupiah di sektor tambang dan migas.</p>\\n        "}, {"key": "toefl", "title": "Panduan Skor TOEFL ITP, Prediction, dan IELTS untuk Syarat BUMN & CPNS 2026", "category": "Sertifikasi Bahasa", "tags": ["TOEFL ITP", "Prediction Test", "Syarat BUMN", "CPNS 2026"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Jangan Sampai Salah Ikut Tes:</strong> Banyak pelamar gugur administrasi di Rekrutmen Bersama BUMN (RBB) atau CPNS Kementerian Luar Negeri karena mengunggah sertifikat TOEFL Prediction padahal instansi mewajibkan sertifikat resmi **TOEFL ITP resmi ETS**. Pahami ketentuannya secara tepat.\\n            </div>\\n\\n            <h2 id=\\"beda-toefl\\">1. Perbedaan Mendasar TOEFL ITP, Prediction, dan IELTS</h2>\\n            <ul>\\n                <li><strong>TOEFL ITP (Institutional Testing Program)</strong>: Dikeluarkan langsung oleh institusi resmi Educational Testing Service (ETS) Amerika Serikat melalui lembaga bahasa berlisensi di Indonesia. Skor berkisar 310 - 677. Format Paper-Based Test (PBT) terdiri dari Listening Comprehension, Structure & Written Expression, dan Reading Comprehension.</li>\\n                <li><strong>TOEFL Prediction</strong>: Ujian simulasi yang diselenggarakan oleh lembaga kursus lokal. Biaya jauh lebih murah (Rp 50.000 - Rp 150.000), namun <em>hanya diterima oleh sebagian perusahaan swasta lokal</em> dan ditolak oleh instansi pemerintah resmi.</li>\\n                <li><strong>IELTS (International English Language Testing System)</strong>: Dikelola oleh British Council / IDP dengan rentang band skor 1.0 - 9.0. Menguji 4 kemampuan lengkap termasuk Speaking dan Writing langsung dengan penutur asli.</li>\\n            </ul>\\n\\n            <h2 id=\\"standar-bumn\\">2. Standar Skor Minimum Rekrutmen Bersama BUMN (RBB) &amp; CPNS</h2>\\n            <table style=\\"width:100%; border-collapse:collapse; margin:20px 0; font-size:13.5px;\\">\\n                <thead>\\n                    <tr style=\\"background:#f1f5f9; border-bottom:2px solid #cbd5e1;\\">\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Instansi / Perusahaan</th>\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Jenis Sertifikat yang Diterima</th>\\n                        <th style=\\"padding:10px 14px; text-align:left;\\">Skor Minimal</th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">PT Pertamina (Persero)</td>\\n                        <td style=\\"padding:10px 14px;\\">TOEFL ITP / IELTS Resmi</td>\\n                        <td style=\\"padding:10px 14px;\\">500 (ITP) / 6.0 (IELTS)</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">PT Telkom Indonesia</td>\\n                        <td style=\\"padding:10px 14px;\\">TOEFL ITP / TOEIC</td>\\n                        <td style=\\"padding:10px 14px;\\">500 (ITP) / 650 (TOEIC)</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Bank Mandiri & BRI (BUMN)</td>\\n                        <td style=\\"padding:10px 14px;\\">TOEFL ITP / Prediction Terakreditasi</td>\\n                        <td style=\\"padding:10px 14px;\\">450 - 500</td>\\n                    </tr>\\n                    <tr style=\\"border-bottom:1px solid #e2e8f0;\\">\\n                        <td style=\\"padding:10px 14px; font-weight:700;\\">Kementerian Luar Negeri (Kemenlu)</td>\\n                        <td style=\\"padding:10px 14px;\\">TOEFL ITP / IELTS Resmi</td>\\n                        <td style=\\"padding:10px 14px;\\">550 (ITP) / 6.5 (IELTS)</td>\\n                    </tr>\\n                </tbody>\\n            </table>\\n\\n            <h2 id=\\"trik-30-hari\\">3. Roadmap Belajar 30 Hari Mendongkrak Skor 500+</h2>\\n            <ul>\\n                <li><strong>Minggu 1 (Fokus Structure & Written Expression)</strong>: Pelajari 15 aturan tata bahasa krusial: Subjek-Predikat Inversi, Penggunaan Klausa Relatif (*Who/Which/That*), Pola Parallel Structure, dan Concord/Agreement. Bagian Structure adalah bagian yang paling cepat ditingkatkan nilainya dalam waktu singkat!</li>\\n                <li><strong>Minggu 2 (Listening Comprehension Part A)</strong>: Latih telinga Anda untuk menangkap sinonim kata pada pembicara kedua (*Second Speaker Strategy*). Kunci jawaban di Part A hampir selalu merupakan pengulangan kalimat pembicara kedua dalam kata lain.</li>\\n                <li><strong>Minggu 3 (Reading Comprehension Skimming & Scanning)</strong>: Jangan membaca seluruh teks paragraf dari awal. Baca pertanyaan terlebih dahulu, temukan kata kunci utama, lalu lakukan scanning baris teks yang bersangkutan.</li>\\n                <li><strong>Minggu 4 (Simulasi Full Test CAT)</strong>: Kerjakan minimal 3 paket simulasi lengkap 140 soal dalam batas waktu 115 menit tanpa jeda untuk membangun ketahanan fokus.</li>\\n            </ul>\\n        "}, {"key": "bnsp", "title": "Cara Memperoleh Sertifikat Profesi BNSP untuk Meningkatkan Nilai Tawar Gaji", "category": "Sertifikasi Profesi", "tags": ["Sertifikasi BNSP", "Uji Kompetensi", "Standar Profesi"], "content": "\\n            <div class=\\"hk-callout-box\\">\\n                <strong>📌 Mengapa Sertifikat BNSP Diakui Negara?</strong> Badan Nasional Sertifikasi Profesi (BNSP) adalah badan independen yang bertanggung jawab langsung kepada Presiden RI untuk menjamin kompetensi tenaga kerja Indonesia berdasarkan Standar Kompetensi Kerja Nasional Indonesia (SKKNI).\\n            </div>\\n\\n            <h2 id=\\"apa-itu-bnsp\\">1. Mengenal BNSP &amp; Lembaga Sertifikasi Profesi (LSP)</h2>\\n            <p>Sertifikat BNSP memiliki logo Garuda Pancasila emas resmi. Berbeda dengan sertifikat pelatihan (*Certificate of Attendance*) yang hanya menyatakan Anda pernah hadir kursus, Sertifikat Kompetensi BNSP membuktikan secara legal formal bahwa Anda <strong>KOMPETEN</strong> melakukan pekerjaan sesuai standar industri setelah diuji oleh Asesor bersertifikat.</p>\\n\\n            <h2 id=\\"skema-populer\\">2. Skema Kompetensi Paling Diminati Rekruter</h2>\\n            <ul>\\n                <li><strong>Digital Marketing</strong>: Pengelolaan kampanye iklan, SEO, dan media sosial.</li>\\n                <li><strong>Human Resource Management (HRD)</strong>: Staf Rekrutmen, Payroll, dan Hubungan Industrial.</li>\\n                <li><strong>Akuntansi &amp; Keuangan</strong>: Teknisi Akuntansi Yunior & Pengelola Pajak.</li>\\n                <li><strong>Pengadaan Barang dan Jasa</strong>: Procurement Officer dan Logistik.</li>\\n            </ul>\\n\\n            <h2 id=\\"tahapan-asesmen\\">3. Alur Pendaftaran &amp; Tahapan Uji Asesmen</h2>\\n            <ol>\\n                <li><strong>Pendaftaran via LSP Terlisensi</strong>: Memilih skema okupasi yang sesuai dengan latar belakang Anda.</li>\\n                <li><strong>Pengisian Asesmen Mandiri (FR-APL-01 &amp; FR-APL-02)</strong>: Menandai bukti kompetensi yang telah Anda miliki.</li>\\n                <li><strong>Pengumpulan Portofolio Bukti Kerja</strong>: Menyertakan contoh laporan kerja, surat rekomendasi atasan, karya desain, atau sertifikat pendukung.</li>\\n                <li><strong>Pelaksanaan Asesmen (Uji Kompetensi)</strong>: Wawancara mendalam bersama Asesor, ujian tertulis/studi kasus, dan demonstrasi simulasi praktik kerja.</li>\\n                <li><strong>Keputusan Asesmen</strong>: Dinyatakan K (Kompeten) atau BK (Belum Kompeten).</li>\\n            </ol>\\n\\n            <h2 id=\\"nilai-tambah\\">4. Nilai Tambah pada Negosiasi Gaji</h2>\\n            <p>Kandidat yang mencantumkan nomor registrasi sertifikat BNSP di resume memiliki keunggulan kompetitif di mata rekruter korporasi karena perusahaan tidak perlu mengeluarkan biaya pelatihan dasar lagi. Hal ini memberikan posisi tawar yang jauh lebih kuat saat bernegosiasi gaji pokok dan benefit awal.</p>\\n        "}]';
    $articles = json_decode($raw_json, true);
    if (!is_array($articles)) {
        return 0;
    }

    $created_count = 0;
    $parent_cat_id = hakajobs_get_or_create_category(__('Tips & Karir', 'hakajobs'));

    $admin_users = get_users(array('role' => 'administrator', 'number' => 1));
    $author_id = !empty($admin_users) ? $admin_users[0]->ID : (get_current_user_id() ? get_current_user_id() : 1);

    foreach ($articles as $art) {
        $existing = get_page_by_title($art['title'], OBJECT, 'post');
        if ($existing) {
            continue;
        }

        // Kategori spesifik
        $cat_ids = array();
        if ($parent_cat_id > 0) {
            $cat_ids[] = $parent_cat_id;
        }
        if (!empty($art['category'])) {
            $sub_cat_id = hakajobs_get_or_create_category($art['category'], $parent_cat_id);
            if ($sub_cat_id > 0) {
                $cat_ids[] = $sub_cat_id;
            }
        }

        $post_id = wp_insert_post(array(
            'post_title'    => $art['title'],
            'post_content'  => $art['content'],
            'post_status'   => 'publish',
            'post_type'     => 'post',
            'post_author'   => $author_id,
            'post_category' => $cat_ids,
            'tags_input'    => $art['tags'],
        ));

        if ($post_id && !is_wp_error($post_id)) {
            $created_count++;
        }
    }

    return $created_count;
}

/**
 * Otomatis instal artikel awal satu kali di Dashboard Admin jika Pos masih kosong
 */
function hakajobs_auto_install_starter_articles() {
    if (!is_admin()) {
        return;
    }
    if (get_option('hakajobs_starter_articles_v1')) {
        return;
    }

    // Periksa apakah belum ada postingan sama sekali di menu Pos
    $count = wp_count_posts('post');
    if (isset($count->publish) && (int)$count->publish === 0) {
        hakajobs_generate_starter_articles();
    }

    update_option('hakajobs_starter_articles_v1', '1');
}
add_action('admin_init', 'hakajobs_auto_install_starter_articles');
